mapper.select:
SELECT seq
FROM notification_seq
WHERE user_id = #{userId} AND scope = #{scope}

SELECT last_read_seq
FROM notification_read
WHERE user_id = #{userId} AND scope = #{scope}

SELECT ,
       (n.seq <= COALESCE(r.last_read_seq, 0)) AS is_read
FROM notification n
LEFT JOIN notification_read r ON r.user_id = n.user_id AND r.scope = n.scope
WHERE n.user_id = #{userId}

    AND n.scope = #{scope}

ORDER BY n.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM notification n
WHERE n.user_id = #{userId}

    AND n.scope = #{scope}
